/** `soprano-photo` is the clarinet when the photograph is not shown (see icon-photos.js). */
export const iconNodes = (name) => (name === 'soprano-photo' ? CUSTOM.clarinet : CUSTOM[name] ?? LIBRARY[name] ?? data[name] ?? null);
/**
 * The instrument icons are drawn a little LIGHTER than the other icons of the interface (the strokes were judged too heavy): the weight is a factor on the stroke width
 * of the group (2 → 1.6) and on the widths some icons give to their details. `thinNodes(nodes, factor)` returns the nodes with those widths scaled.
 */
export const INSTRUMENT_WEIGHT = 0.8;
export const thinNodes = (nodes, factor = INSTRUMENT_WEIGHT) => nodes.map(([tag, a]) => [tag, a['stroke-width'] != null ? { ...a, 'stroke-width': String(Math.round(Number(a['stroke-width']) * factor * 100) / 100) } : a]);
export const hasIconShape = (name) => Boolean(iconNodes(name));
export const iconShapeNames = () => [...Object.keys(data), ...Object.keys(CUSTOM), ...Object.keys(LIBRARY)];
